function parseThresholds(thresholdStrings?: string[]): { [key: string]: number } | null {
  if (!thresholdStrings || thresholdStrings.length === 0) {
    return null;
  }

  const thresholds: { [key: string]: number } = {};
  const validMetrics = ['exact_match', 'toxicity', 'length_variance'];

  for (const threshStr of thresholdStrings) {
    const parts = threshStr.split('=');
    if (parts.length !== 2) {
      throw {
        code: 2,
        message: `Malformed threshold: "${threshStr}". Expected format: <metric>=<number>`
      };
    }

    const [metric, value] = parts;
    const numValue = Number.parseFloat(value);

    if (Number.isNaN(numValue)) {
      throw {
        code: 2,
        message: `Invalid threshold value for "${metric}": "${value}" is not a number`
      };
    }

    if (numValue < 0 || numValue > 1) {
      throw {
        code: 2,
        message: `Invalid threshold value for "${metric}": ${numValue} is outside the range [0, 1]`
      };
    }

    if (!validMetrics.includes(metric)) {
      throw {
        code: 2,
        message: `Unknown metric: "${metric}". Valid metrics are: ${validMetrics.join(', ')}`
      };
    }

    thresholds[metric] = numValue;
  }

  return thresholds;
}

function runEvalCommand(options: EvalOptions) {
  assertFileExists(options.outputs);

  let thresholds: { [key: string]: number } | null = null;
  try {
    thresholds = parseThresholds(options.threshold);
  } catch (error: any) {
    log.error(error.message);
    process.exit(error.code ?? 1);
  }

  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
    outputsPath: options.outputs,
    referencesPath: options.references
  });
  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
    outputs: dataset.outputs,
    references: dataset.references
  });
  const reportConfig: any = {
    evaluations,
    outputsPath: dataset.outputsPath,
    referencesPath: dataset.referencesPath
  };
  if (thresholds) {
    reportConfig.thresholds = thresholds;
  }
  const report = (Eval.generateReport as unknown as (config: unknown) => any)(reportConfig);
  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
    report,
    format: options.format ?? 'json',
    reportPath: options.report
  });
  log.success('Evaluation report generated.', { path: resolvedPath });

  if (thresholds && report.passed === false) {
    process.exit(1);
  }
}

