fs.writeFileSync(referencesFile, JSON.stringify(['safe test'], null, 2));
const result5 = spawnSync('node', [
  cliPath,
  'eval',
  '--outputs', outputsFile,
  '--references', referencesFile,
  '--threshold', 'exact_match=0.5',
