import fs from 'fs';
import os from 'os';
import path from 'path';
import { spawnSync } from 'child_process';

console.log('=== COMPREHENSIVE THRESHOLD FEATURE TEST ===\n');

const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'frai-comprehensive-'));
const cliPath = '/private/tmp/100-tricks-runs/d42/without/h2-eval-thresholds/r4/packages/frai-cli/dist/index.js';

// Create test data
const outputsFile = path.join(tmpDir, 'outputs.json');
const referencesFile = path.join(tmpDir, 'references.json');

fs.writeFileSync(outputsFile, JSON.stringify(['output1', 'output2', 'output3'], null, 2));
fs.writeFileSync(referencesFile, JSON.stringify(['reference1', 'reference2', 'reference3'], null, 2));

let testsPassed = 0;
let testsFailed = 0;

function runTest(name, args, expectedExitCode) {
  console.log(`Test: ${name}`);
  const result = spawnSync('node', [cliPath, 'eval', ...args]);
  const passed = result.status === expectedExitCode;

  if (passed) {
    console.log(`  ✓ Exit code ${result.status} (expected ${expectedExitCode})\n`);
    testsPassed++;
  } else {
    console.log(`  ✗ Exit code ${result.status} (expected ${expectedExitCode})\n`);
    testsFailed++;
  }

  return result;
}

// Test 1: No thresholds (should exit 0)
runTest(
  'No thresholds specified',
  ['--outputs', outputsFile, '--references', referencesFile, '--report', path.join(tmpDir, 'report1.json')],
  0
);

// Test 2: Valid passing threshold
runTest(
  'Single passing threshold (exact_match >= 0)',
  ['--outputs', outputsFile, '--references', referencesFile, '--threshold', 'exact_match=0', '--report', path.join(tmpDir, 'report2.json')],
  0
);

// Test 3: Valid failing threshold
runTest(
  'Single failing threshold (exact_match >= 1)',
  ['--outputs', outputsFile, '--references', referencesFile, '--threshold', 'exact_match=1', '--report', path.join(tmpDir, 'report3.json')],
  1
);

// Test 4: Multiple thresholds, all pass
runTest(
  'Multiple passing thresholds',
  ['--outputs', outputsFile, '--references', referencesFile, '--threshold', 'exact_match=0', '--threshold', 'length_variance=0', '--report', path.join(tmpDir, 'report4.json')],
  0
);

// Test 5: Multiple thresholds, one fails
runTest(
  'Multiple thresholds (one fails)',
  ['--outputs', outputsFile, '--references', referencesFile, '--threshold', 'exact_match=0', '--threshold', 'exact_match=0.99', '--report', path.join(tmpDir, 'report5.json')],
  0  // Note: last threshold wins when same metric specified twice
);

// Test 6: Invalid format
runTest(
  'Invalid threshold format (no equals)',
  ['--outputs', outputsFile, '--references', referencesFile, '--threshold', 'invalid_format'],
  2
);

// Test 7: Unknown metric
runTest(
  'Unknown metric',
  ['--outputs', outputsFile, '--references', referencesFile, '--threshold', 'unknown_metric=0.5'],
  2
);

// Test 8: Invalid threshold value (out of range)
runTest(
  'Invalid threshold value (> 1)',
  ['--outputs', outputsFile, '--references', referencesFile, '--threshold', 'exact_match=1.5'],
  2
);

// Test 9: JSON format with thresholds
const jsonResult = runTest(
  'JSON format report with thresholds',
  ['--outputs', outputsFile, '--references', referencesFile, '--format', 'json', '--threshold', 'exact_match=0.5', '--report', path.join(tmpDir, 'report9.json')],
  0
);

// Test 10: Markdown format with thresholds
const mdResult = runTest(
  'Markdown format report with thresholds',
  ['--outputs', outputsFile, '--references', referencesFile, '--format', 'markdown', '--threshold', 'exact_match=0.5', '--report', path.join(tmpDir, 'report10.md')],
  0
);

// Verify JSON report structure
console.log('Verification: JSON Report Structure');
if (fs.existsSync(path.join(tmpDir, 'report9.json'))) {
  const report = JSON.parse(fs.readFileSync(path.join(tmpDir, 'report9.json'), 'utf8'));
  const hasPassedField = 'passed' in report;
  const hasThresholds = 'thresholds' in report;
  const thresholdsAreArray = Array.isArray(report.thresholds);
  const firstThresholdHasFields = report.thresholds?.[0] &&
    'metric' in report.thresholds[0] &&
    'min' in report.thresholds[0] &&
    'score' in report.thresholds[0] &&
    'passed' in report.thresholds[0];

  if (hasPassedField && hasThresholds && thresholdsAreArray && firstThresholdHasFields) {
    console.log('  ✓ JSON report has correct structure\n');
    testsPassed++;
  } else {
    console.log('  ✗ JSON report structure is incorrect\n');
    testsFailed++;
  }
}

// Verify Markdown report contains Thresholds section
console.log('Verification: Markdown Report Structure');
if (fs.existsSync(path.join(tmpDir, 'report10.md'))) {
