3	
4	import {
5	  DEFAULT_METRICS,
6	  exactMatchMetric,
7	  lengthVarianceMetric,
8	  toxicityMetric
9	} from './metrics.js';
10	import { resolveReportPath, toJson, toMarkdown } from './reporters.js';
11	
12	const defaultFs = fs;
13	
14	const ensureArray = (value) => (Array.isArray(value) ? value : []);
15	
16	export function loadDataset({ outputsPath, referencesPath, fs: fsModule = defaultFs } = {}) {
17	  if (!outputsPath) {
18	    throw new Error('outputsPath is required for evaluation.');
19	  }
20	
21	  const outputsAbsolute = path.resolve(outputsPath);
22	  const outputsRaw = fsModule.readFileSync(outputsAbsolute, 'utf8');
23	  const outputs = JSON.parse(outputsRaw);
24	
25	  let references = [];
26	  let referencesAbsolute = null;
27	  if (referencesPath) {
28	    referencesAbsolute = path.resolve(referencesPath);
29	    const referencesRaw = fsModule.readFileSync(referencesAbsolute, 'utf8');
30	    references = JSON.parse(referencesRaw);
31	  }
32	
33	  return {
34	    outputs,
35	    references,
36	    outputsPath: outputsAbsolute,
37	    referencesPath: referencesAbsolute
38	  };
39	}
40	
41	export function runEvaluations({
42	  outputs,
43	  references,
44	  metrics = DEFAULT_METRICS
45	} = {}) {
46	  const outs = ensureArray(outputs);
47	  const refs = ensureArray(references);
48	
49	  const evaluations = metrics.map((metric) => {
50	    if (typeof metric === 'function') {
51	      return metric(outs, refs);
52	    }
53	    if (metric && typeof metric.evaluate === 'function') {
54	      return metric.evaluate(outs, refs);
55	    }
56	    throw new Error('Invalid metric supplied to runEvaluations.');
57	  });
58	
59	  return evaluations;
60	}
61	
62	/**
63	 * Generate an evaluation report from metric results.
64	 * @param {Object} config - Configuration object
65	 * @param {Array} config.evaluations - Metric evaluation results from runEvaluations
66	 * @param {string} config.outputsPath - Path to the outputs file
67	 * @param {string} [config.referencesPath] - Path to the references file
68	 * @param {string} [config.generatedAt] - ISO timestamp (defaults to now)
69	 * @param {Object} [config.thresholds] - Metric score thresholds to gate on (e.g., { exact_match: 0.9 })
70	 * @returns {Object} Report object with metadata, metrics, and optional thresholds/passed status
71	 */
72	export function generateReport({
73	  evaluations,
74	  outputsPath,
75	  referencesPath,
76	  generatedAt = new Date().toISOString(),
77	  thresholds
78	} = {}) {
79	  const totalSamples = evaluations.reduce((total, metric) => {
80	    if (typeof metric.total === 'number') return Math.max(total, metric.total);
81	    return total;
82	  }, 0);
83	
84	  const report = {
85	    metadata: {
86	      generatedAt,
87	      outputsPath,
88	      referencesPath,
89	      totalSamples
90	    },
91	    metrics: evaluations
92	  };
93	
94	  if (thresholds && Object.keys(thresholds).length > 0) {
95	    const thresholdResults = [];
96	    let allPassed = true;
97	
98	    for (const [metricId, minScore] of Object.entries(thresholds)) {
99	      const metric = evaluations.find((m) => m.id === metricId);
100	      const score = metric?.score ?? null;
101	      const passed = score !== null && score >= minScore;
102	
103	      if (!passed) {
104	        allPassed = false;
105	      }
106	
107	      thresholdResults.push({
108	        metric: metricId,
109	        min: minScore,
110	        score,
111	        passed
112	      });
113	    }
114	
115	    report.passed = allPassed;
116	    report.thresholds = thresholdResults;
117	  }
118	
119	  return report;
120	}
121	
122	export function writeReport({
123	  report,
124	  format = 'json',
125	  reportPath,
126	  fs: fsModule = defaultFs
